package com.commercecore.promotion;

import com.commercecore.audit.AuditService;import com.commercecore.category.*;import com.commercecore.common.exception.ApiException;import com.commercecore.product.*;import com.commercecore.user.*;
import org.springframework.dao.DataIntegrityViolationException;import org.springframework.data.domain.Sort;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.*;import java.util.*;

@Service
public class PromotionService{
 private final PromotionRepository promotions;private final PromotionRedemptionRepository redemptions;private final ProductRepository products;private final CategoryRepository categories;private final UserAccountRepository users;private final Clock clock;private final AuditService audits;
 public PromotionService(PromotionRepository p,PromotionRedemptionRepository r,ProductRepository products,CategoryRepository categories,UserAccountRepository users,Clock clock,AuditService audits){promotions=p;redemptions=r;this.products=products;this.categories=categories;this.users=users;this.clock=clock;this.audits=audits;}
 @Transactional public PromotionDtos.PromotionResponse create(UUID actorId,PromotionDtos.PromotionRequest request){String code=code(request.code());if(promotions.existsByCode(code))throw duplicate();Promotion p=build(null,request,code);try{promotions.saveAndFlush(p);}catch(DataIntegrityViolationException e){throw duplicate();}audits.record(actorId,"PROMOTION_CREATED","PROMOTION","PROMOTION",p.getId().toString(),"code="+p.getCode()+"; name="+p.getName());return response(p);}
 @Transactional public PromotionDtos.PromotionResponse update(UUID actorId,UUID id,PromotionDtos.PromotionRequest request){Promotion p=required(id);String code=code(request.code());if(promotions.existsByCodeAndIdNot(code,id))throw duplicate();Targets t=targets(request);try{p.update(code,request.name(),request.description(),request.type(),request.scope(),request.discountValue(),money(request.minimumSpend()),nullableMoney(request.maximumDiscount()),request.startsAt(),request.endsAt(),request.totalUsageLimit(),request.perUserUsageLimit(),request.active(),t.product(),t.category());promotions.flush();}catch(IllegalArgumentException|DataIntegrityViolationException e){throw invalid();}audits.record(actorId,"PROMOTION_UPDATED","PROMOTION","PROMOTION",p.getId().toString(),"code="+p.getCode()+"; active="+p.isActive());return response(p);}
 @Transactional public PromotionDtos.PromotionResponse activate(UUID actorId,UUID id){Promotion p=required(id);p.activate();audits.record(actorId,"PROMOTION_ACTIVATED","PROMOTION","PROMOTION",p.getId().toString(),"code="+p.getCode());return response(p);}@Transactional public PromotionDtos.PromotionResponse deactivate(UUID actorId,UUID id){Promotion p=required(id);p.deactivate();audits.record(actorId,"PROMOTION_DEACTIVATED","PROMOTION","PROMOTION",p.getId().toString(),"code="+p.getCode());return response(p);}
 @Transactional(readOnly=true)public List<PromotionDtos.PromotionResponse> list(){return promotions.findAll(Sort.by("createdAt")).stream().map(this::response).toList();}@Transactional(readOnly=true)public PromotionDtos.PromotionResponse get(UUID id){return response(required(id));}
 @Transactional(readOnly=true)public Promotion findByCode(String raw){return promotions.findByCode(code(raw)).orElseThrow(()->error(HttpStatus.NOT_FOUND,"PROMOTION_NOT_FOUND","Promotion was not found."));}
 @Transactional(readOnly=true)public Evaluation evaluate(Promotion p,UUID userId,List<PricingLine> lines){
  Instant now=clock.instant();if(!p.isActive())return invalidEval("PROMOTION_INACTIVE","Promotion is inactive.");if(now.isBefore(p.getStartsAt()))return invalidEval("PROMOTION_NOT_STARTED","Promotion has not started.");if(!now.isBefore(p.getEndsAt()))return invalidEval("PROMOTION_EXPIRED","Promotion has expired.");
  long total=redemptions.countByPromotionId(p.getId());if(p.getTotalUsageLimit()!=null&&total>=p.getTotalUsageLimit())return invalidEval("PROMOTION_USAGE_LIMIT_REACHED","Promotion usage limit has been reached.");
  long user=redemptions.countByPromotionIdAndUserId(p.getId(),userId);if(p.getPerUserUsageLimit()!=null&&user>=p.getPerUserUsageLimit())return invalidEval("PROMOTION_USER_LIMIT_REACHED","Promotion user limit has been reached.");
  BigDecimal eligible=lines.stream().filter(line->eligible(p,line.product())).map(PricingLine::subtotal).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);
  if(eligible.signum()<=0||eligible.compareTo(p.getMinimumSpend())<0)return invalidEval("PROMOTION_NOT_ELIGIBLE","Cart merchandise is not eligible for this promotion.");
  if(p.getType()==PromotionType.FREE_SHIPPING)return new Evaluation(true,null,null,eligible,BigDecimal.ZERO.setScale(2),true);
  BigDecimal discount=p.getType()==PromotionType.PERCENTAGE?eligible.multiply(p.getDiscountValue()).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP):p.getDiscountValue().setScale(2,RoundingMode.HALF_UP);
  if(p.getMaximumDiscount()!=null)discount=discount.min(p.getMaximumDiscount());discount=discount.min(eligible).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);
  return new Evaluation(true,null,null,eligible,discount,false);
 }
 @Transactional public UUID recordRedemption(UUID promotionId,UUID userId,String referenceKey){
  Promotion p=promotions.findLockedById(promotionId).orElseThrow(PromotionService::notFound);String ref=referenceKey==null?null:referenceKey.trim();Optional<PromotionRedemption> prior=redemptions.findByPromotionIdAndReferenceKey(promotionId,ref);if(prior.isPresent())return prior.get().getId();
  Instant now=clock.instant();if(!p.isActive())throw evaluationError(invalidEval("PROMOTION_INACTIVE","Promotion is inactive."));if(now.isBefore(p.getStartsAt()))throw evaluationError(invalidEval("PROMOTION_NOT_STARTED","Promotion has not started."));if(!now.isBefore(p.getEndsAt()))throw evaluationError(invalidEval("PROMOTION_EXPIRED","Promotion has expired."));
  if(p.getTotalUsageLimit()!=null&&redemptions.countByPromotionId(promotionId)>=p.getTotalUsageLimit())throw evaluationError(invalidEval("PROMOTION_USAGE_LIMIT_REACHED","Promotion usage limit has been reached."));
  if(p.getPerUserUsageLimit()!=null&&redemptions.countByPromotionIdAndUserId(promotionId,userId)>=p.getPerUserUsageLimit())throw evaluationError(invalidEval("PROMOTION_USER_LIMIT_REACHED","Promotion user limit has been reached."));
  UserAccount user=users.findById(userId).orElseThrow(()->error(HttpStatus.NOT_FOUND,"USER_NOT_FOUND","User was not found."));try{return redemptions.saveAndFlush(new PromotionRedemption(p,user,ref)).getId();}catch(IllegalArgumentException|DataIntegrityViolationException e){throw error(HttpStatus.CONFLICT,"PROMOTION_REDEMPTION_CONFLICT","Promotion redemption conflicts with existing data.");}
 }
 public ApiException evaluationError(Evaluation e){return error(HttpStatus.CONFLICT,e.errorCode(),e.message());}
 private boolean eligible(Promotion p,Product product){if(p.getScope()==PromotionScope.CART)return true;if(p.getScope()==PromotionScope.PRODUCT)return p.getTargetProduct().getId().equals(product.getId());Category c=product.getCategory();while(c!=null){if(c.getId().equals(p.getTargetCategory().getId()))return true;c=c.getParentCategory();}return false;}
 private Promotion build(UUID id,PromotionDtos.PromotionRequest r,String code){Targets t=targets(r);try{return new Promotion(code,r.name(),r.description(),r.type(),r.scope(),r.discountValue(),money(r.minimumSpend()),nullableMoney(r.maximumDiscount()),r.startsAt(),r.endsAt(),r.totalUsageLimit(),r.perUserUsageLimit(),r.active(),t.product(),t.category());}catch(IllegalArgumentException e){throw invalid();}}
 private Targets targets(PromotionDtos.PromotionRequest r){Product p=r.targetProductId()==null?null:products.findById(r.targetProductId()).orElseThrow(()->error(HttpStatus.NOT_FOUND,"PRODUCT_NOT_FOUND","The product was not found."));Category c=r.targetCategoryId()==null?null:categories.findById(r.targetCategoryId()).orElseThrow(()->error(HttpStatus.NOT_FOUND,"CATEGORY_NOT_FOUND","The category was not found."));return new Targets(p,c);}
 private PromotionDtos.PromotionResponse response(Promotion p){return new PromotionDtos.PromotionResponse(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.getType(),p.getScope(),p.getDiscountValue(),p.getMinimumSpend(),p.getMaximumDiscount(),p.getStartsAt(),p.getEndsAt(),p.getTotalUsageLimit(),p.getPerUserUsageLimit(),p.isActive(),p.getTargetProduct()==null?null:p.getTargetProduct().getId(),p.getTargetCategory()==null?null:p.getTargetCategory().getId(),redemptions.countByPromotionId(p.getId()),p.getCreatedAt(),p.getUpdatedAt());}
 private Promotion required(UUID id){return promotions.findById(id).orElseThrow(PromotionService::notFound);}private static ApiException notFound(){return error(HttpStatus.NOT_FOUND,"PROMOTION_NOT_FOUND","Promotion was not found.");}
 private static String code(String raw){try{return Promotion.normalizeCode(raw);}catch(IllegalArgumentException e){throw invalid();}}private static BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}private static BigDecimal nullableMoney(BigDecimal v){return v==null?null:money(v);}
 private static Evaluation invalidEval(String code,String message){return new Evaluation(false,code,message,BigDecimal.ZERO.setScale(2),BigDecimal.ZERO.setScale(2),false);}private static ApiException duplicate(){return error(HttpStatus.CONFLICT,"DUPLICATE_PROMOTION_CODE","Promotion code is already in use.");}private static ApiException invalid(){return error(HttpStatus.BAD_REQUEST,"PROMOTION_INVALID","Promotion configuration is invalid.");}private static ApiException error(HttpStatus s,String c,String m){return new ApiException(s,c,m);}
 public record PricingLine(Product product,BigDecimal subtotal){}public record Evaluation(boolean valid,String errorCode,String message,BigDecimal eligibleSubtotal,BigDecimal discount,boolean freeShipping){}private record Targets(Product product,Category category){}
}
